output_text:
[
  {
    "id": "entry_cart_mandatory",
    "text": "A shopper must take the entry cart from the cart station before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "holding_cart": "hasCart"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "holding_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "Items may only be picked up while the shopper has a cart, not while shopping cart-free.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup",
          "without_cart"
        ]
      }
    }
  },
  {
    "id": "no_hand_carried_groceries",
    "text": "Groceries must not be carried by hand; they should be transported in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "using_cart": "hasCart"
      },
      "events": {
        "take_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_to_northwest_bay",
    "text": "After taking a cart, the shopper must return it to the northwest cart-return bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_bay": "at(0,1)",
        "cart_parked_in_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "northwest_cart_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_exit_with_unreturned_cart",
    "text": "A shopper may not exit unless the cart has already been parked in the northwest return bay.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)",
        "still_has_cart": "hasCart",
        "cart_not_returned": {
          "not": "cart_returned"
        }
      },
      "events": {
        "attempt_exit": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "attempt_exit",
          {
            "or": [
              "still_has_cart",
              "cart_not_returned"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "cart_drop_only_at_bay",
    "text": "Carts may only be put down at the designated northwest cart-return bay.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "away_from_cart_return_bay": {
          "not": "at_cart_return_bay"
        }
      },
      "events": {
        "drop_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          "away_from_cart_return_bay"
        ]
      }
    }
  },
  {
    "id": "cart_west_wall_one_way",
    "text": "When pushing a cart in the west-wall return lane, the shopper must not turn east or south and should continue toward the return bay.",
    "abstraction": {
      "state_properties": {
        "west_wall_return_lane": {
          "or": [
            "at(0,1)",
            "at(0,2)",
            "at(0,3)",
            "at(0,4)"
          ]
        },
        "pushing_cart": "hasCart",
        "leaving_return_lane": {
          "or": [
            "E",
            "S"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pushing_cart",
          "west_wall_return_lane",
          "leaving_return_lane"
        ]
      }
    }
  },
  {
    "id": "cart_turns_back_from_east_shelves",
    "text": "After reaching the eastern shelf area with a cart, the shopper may not continue east or south toward the exit with the cart.",
    "abstraction": {
      "state_properties": {
        "eastern_shelf_cart_cell": {
          "and": [
            "hasCart",
            {
              "or": [
                "at(6,4)",
                "at(6,2)"
              ]
            }
          ]
        },
        "toward_exit_with_cart": {
          "or": [
            "E",
            "S"
          ]
        }
      },
      "events": {
        "eastern_shelf_interaction": {
          "pre": {
            "and": [
              "eastern_shelf_cart_cell",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "eastern_shelf_cart_cell",
          "toward_exit_with_cart"
        ]
      }
    }
  }
]
